.cm-footer-ctas{display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:.7rem;margin:.85rem auto 0;max-width:100%}
.cm-footer-ctas .cm-powered-by{margin:0}
.cm-grok-bot-cta{align-items:center;background:#fff;border:1px solid rgba(17,24,39,.1);border-radius:999px;box-shadow:0 1px 2px rgba(15,23,42,.05),0 10px 24px rgba(15,23,42,.05);color:#111827;display:inline-flex;font-family:Inter,ui-sans-serif,system-ui,sans-serif;gap:.55rem;height:2.4rem;padding:0 1rem 0 .42rem;text-decoration:none;transition:background .16s ease,border-color .16s ease,box-shadow .16s ease,transform .16s ease,color .16s ease}
.cm-grok-bot-cta:hover{border-color:rgba(246,189,17,.55);box-shadow:0 8px 22px rgba(15,23,42,.1);color:#0a0a0a;transform:translateY(-1px)}
.cm-grok-bot-cta:focus-visible{outline:2px solid #f6bd11;outline-offset:3px}
.cm-grok-bot-cta-mark{align-items:center;display:inline-flex;flex:0 0 auto;height:1.5rem;justify-content:center;position:relative;width:1.5rem}
.cm-grok-bot-cta-mark img{display:block;height:1.25rem;width:1.25rem}
.cm-grok-bot-cta-mark-on-dark{display:none}
.cm-grok-bot-cta-label{font-size:.78rem;font-weight:700;letter-spacing:.005em;line-height:1}
.dark .cm-grok-bot-cta,:root[data-theme="dark"] .cm-grok-bot-cta{background:#0a0a0a;border-color:rgba(255,255,255,.12);box-shadow:0 1px 2px rgba(0,0,0,.35),0 12px 28px rgba(0,0,0,.22);color:#f9fafb}
.dark .cm-grok-bot-cta:hover,:root[data-theme="dark"] .cm-grok-bot-cta:hover{border-color:rgba(246,189,17,.5);box-shadow:0 10px 26px rgba(0,0,0,.4);color:#fff}
.dark .cm-grok-bot-cta-mark-on-light,:root[data-theme="dark"] .cm-grok-bot-cta-mark-on-light{display:none}
.dark .cm-grok-bot-cta-mark-on-dark,:root[data-theme="dark"] .cm-grok-bot-cta-mark-on-dark{display:block}
@media (prefers-color-scheme:dark){
:root:not([data-theme="light"]):not(.dark) .cm-grok-bot-cta{background:#0a0a0a;border-color:rgba(255,255,255,.12);box-shadow:0 1px 2px rgba(0,0,0,.35),0 12px 28px rgba(0,0,0,.22);color:#f9fafb}
:root:not([data-theme="light"]):not(.dark) .cm-grok-bot-cta:hover{border-color:rgba(246,189,17,.5);box-shadow:0 10px 26px rgba(0,0,0,.4);color:#fff}
:root:not([data-theme="light"]):not(.dark) .cm-grok-bot-cta-mark-on-light{display:none}
:root:not([data-theme="light"]):not(.dark) .cm-grok-bot-cta-mark-on-dark{display:block}
